import { Interface, TypedDataEncoder, getBytes, toBeHex, verifyTypedData } from "ethers";
import type { Hex } from "../contracts/index";

import { ReceivingAddress } from "@invisi-labs/core";
import { describe, expect, it } from "vitest";
import { invisiAddressRegistryAbi } from "../contracts/index";
import {
    buildRegistrationCalldata,
    createRegistryReceivingKeyLookup,
    registrationDigest,
    registrationTypedData,
} from "./registry";
import vectors from "./testdata/address-registration-vectors.json";

// Independently generated by current invisi-protocol address-registry-client and ethers TypedDataEncoder.
const context = {
    chainId: 31337n,
    registryAddress: "0x0000000000000000000000000000000000001234" as const,
};
const registration = {
    ownerAddress: "0x7e5f4552091a69125d5dfcb7b8c2659029395bdf" as const,
    keys: {
        viewingPublicKey:
            "0x02eddb7c79146305faaf1b1d994afc1900e183c5792a128472ac59f41bbf87ad42" as const,
        clueKey: "0xc69480518ea88f8cb925fbcd8f5100b1ebc46cc4d8cbe19e0478936567e6b211" as const,
    },
    nonce: 0n,
    deadline: 2000000000n,
};
const digest = () => registrationDigest(context, registration);

describe("wallet-authorized receiving-key registry", () => {
    it("uses the registry EIP-712 domain and flat receiving-key fields", () => {
        const typed = registrationTypedData(context, registration);
        expect(typed.domain).toEqual({
            name: "InvisiAddressRegistry",
            version: "1",
            chainId: context.chainId,
            verifyingContract: context.registryAddress,
        });
        expect(typed.primaryType).toBe("RegisterReceivingKeys");
        expect(typed.message).toEqual({
            walletIdentity: toBeHex(BigInt(registration.ownerAddress), 32),
            ...registration.keys,
            nonce: 0n,
            deadline: registration.deadline,
        });
        expect(TypedDataEncoder.hash(typed.domain, typed.types, typed.message)).toBe(
            registrationDigest(context, registration)
        );
        expect(
            registrationTypedData(context, { ...registration, nonce: 7n }, { update: true })
                .primaryType
        ).toBe("UpdateReceivingKeys");
    });
    it("ABI-encodes distinct register/update calls with full identity and no private authorization material", () => {
        for (const update of [false, true]) {
            const request = { ...registration, nonce: update ? 7n : 0n };
            const built = buildRegistrationCalldata(context, request, "0xaabb", {
                update,
                expectedNonce: request.nonce,
            });
            expect(built.to).toBe(context.registryAddress);
            expect(built.value).toBe(0n);
            const decoded = new Interface(invisiAddressRegistryAbi).parseTransaction({
                data: built.callData,
            })!;
            expect(decoded.name).toBe(update ? "updateKeys" : "registerKeys");
            expect(decoded.args[0].toObject(true)).toEqual({
                keys: request.keys,
                nonce: request.nonce,
                deadline: request.deadline,
                walletIdentity: toBeHex(BigInt(request.ownerAddress), 32),
            });
            expect(decoded.args[1]).toBe("0xaabb");
            expect(Object.keys(built).sort()).toEqual(["callData", "to", "value"]);
        }
    });
    it("binds keys, chain, registry, nonce, deadline, and operation to the authorization digest", () => {
        const changed = [
            registrationTypedData({ ...context, chainId: 1n }, registration),
            registrationTypedData(
                { ...context, registryAddress: "0x0000000000000000000000000000000000005678" },
                registration
            ),
            registrationTypedData(context, {
                ...registration,
                deadline: registration.deadline + 1n,
            }),
            registrationTypedData(context, {
                ...registration,
                keys: { ...registration.keys, clueKey: `0x08${"00".repeat(31)}` },
            }),
            registrationTypedData(context, {
                ...registration,
                keys: {
                    ...registration.keys,
                    viewingPublicKey: `0x03${registration.keys.viewingPublicKey.slice(4)}`,
                },
            }),
            registrationTypedData(context, registration, { update: true }),
            registrationTypedData(context, { ...registration, nonce: 1n }, { update: true }),
        ];
        for (const request of changed)
            expect(TypedDataEncoder.hash(request.domain, request.types, request.message)).not.toBe(
                digest()
            );
    });
    it("rejects malformed identities, both point keys, exhausted/mismatched nonces, expiry, and domains", () => {
        for (const ownerAddress of ["0x1234", `0x${"00".repeat(32)}`, `0x${"ff".repeat(32)}`]) {
            expect(() =>
                registrationTypedData(context, {
                    ...registration,
                    ownerAddress: ownerAddress as Hex,
                })
            ).toThrow();
        }
        for (const key of ["0x00", `0x04${"00".repeat(32)}`, `0x02${"ff".repeat(32)}`]) {
            expect(() =>
                registrationTypedData(context, {
                    ...registration,
                    keys: { ...registration.keys, viewingPublicKey: key as Hex },
                })
            ).toThrow();
        }
        for (const key of [`0x${"00".repeat(32)}`, `0x${"ff".repeat(32)}`, "0x08"]) {
            expect(() =>
                registrationTypedData(context, {
                    ...registration,
                    keys: { ...registration.keys, clueKey: key as Hex },
                })
            ).toThrow();
        }
        for (const nonce of [-1n, 1n, (1n << 64n) - 1n, 1n << 64n]) {
            expect(() => registrationTypedData(context, { ...registration, nonce })).toThrow();
        }
        expect(() =>
            registrationTypedData(
                context,
                { ...registration, nonce: 4n },
                { update: true, expectedNonce: 3n }
            )
        ).toThrow();
        expect(() =>
            registrationTypedData({ ...context, now: registration.deadline + 1n }, registration)
        ).toThrow();
        expect(() =>
            registrationTypedData({ ...context, now: registration.deadline }, registration)
        ).not.toThrow();
        for (const chainId of [-1n, 1n << 64n])
            expect(() => registrationTypedData({ ...context, chainId }, registration)).toThrow();
        expect(() =>
            registrationTypedData(
                { ...context, registryAddress: `0x${"00".repeat(20)}` },
                registration
            )
        ).toThrow();
        expect(() => buildRegistrationCalldata(context, registration, "0x")).not.toThrow();
        for (const proof of ["garbage", "0x1"])
            expect(() => buildRegistrationCalldata(context, registration, proof as Hex)).toThrow();
    });
    it("resolves short and long addresses identically using exactly one receivingKeysOf RPC", async () => {
        let requests = 0;
        const client = {
            provider: null,
            call: async (call: import("ethers").TransactionRequest) => {
                requests++;
                expect(String(call.to).toLowerCase()).toBe(context.registryAddress);
                const iface = new Interface(invisiAddressRegistryAbi);
                expect(iface.parseTransaction({ data: call.data! })!.args[0]).toBe(
                    toBeHex(BigInt(registration.ownerAddress), 32)
                );
                return iface.encodeFunctionResult("receivingKeysOf", [registration.keys, 9n]);
            },
        };
        const lookup = createRegistryReceivingKeyLookup(client, context.registryAddress);
        const receiving = {
            ownerAddress: registration.ownerAddress,
            viewingPublicKey: getBytes(registration.keys.viewingPublicKey),
            clueKey: getBytes(registration.keys.clueKey),
        };
        const long = await ReceivingAddress.parse(
            ReceivingAddress.from(receiving).toString()
        ).resolve(lookup);
        expect(requests).toBe(0);
        expect(
            await ReceivingAddress.parse(
                ReceivingAddress.fromIdentity(registration.ownerAddress).toString()
            ).resolve(lookup)
        ).toEqual(long);
        expect(requests).toBe(1);
    });
    it("propagates lookup RPC failures and rejects returned malformed keys without fallback", async () => {
        const error = new Error("registry unavailable");
        const broken = {
            provider: null,
            call: async () => {
                throw error;
            },
        };
        const lookup = createRegistryReceivingKeyLookup(broken, context.registryAddress);
        await expect(
            ReceivingAddress.parse(
                ReceivingAddress.fromIdentity(registration.ownerAddress).toString()
            ).resolve(lookup)
        ).rejects.toBe(error);
        const malformed = createRegistryReceivingKeyLookup(
            {
                provider: null,
                call: async () =>
                    new Interface(invisiAddressRegistryAbi).encodeFunctionResult(
                        "receivingKeysOf",
                        [{ ...registration.keys, clueKey: `0x${"00".repeat(32)}` }, 1n]
                    ),
            },
            context.registryAddress
        );
        await expect(malformed(registration.ownerAddress)).rejects.toThrow();
    });
});

it.each(vectors.rows)("matches independently signed registration fixture %#", (row) => {
    const context = {
        ...row.context,
        chainId: BigInt(row.context.chainId),
        registryAddress: row.context.registryAddress as Hex,
    };
    const registration = {
        ...row.registration,
        ownerAddress: row.registration.ownerAddress as Hex,
        keys: {
            viewingPublicKey: row.registration.keys.viewingPublicKey as Hex,
            clueKey: row.registration.keys.clueKey as Hex,
        },
        nonce: BigInt(row.registration.nonce),
        deadline: BigInt(row.registration.deadline),
    };
    const typed = registrationTypedData(context, registration, { update: row.update });
    expect(
        JSON.parse(JSON.stringify(typed, (_, v) => (typeof v === "bigint" ? v.toString() : v)))
    ).toEqual(row.typedData);
    expect(registrationDigest(context, registration, { update: row.update })).toBe(row.digest);
    expect(
        verifyTypedData(typed.domain, typed.types, typed.message, row.signature).toLowerCase()
    ).toBe(row.signer.toLowerCase());
    expect(
        buildRegistrationCalldata(context, registration, row.signature as Hex, {
            update: row.update,
        }).callData
    ).toBe(row.callData);
});
